def trans(pt, kind, pivot=(8,0)):
 r,c=pt; a,b=pivot; y=r-a; x=c-b
 if kind=='cw':return (a+x,b-y)
 if kind=='ccw':return (a-x,b+y)
 if kind=='180':return (a-y,b-x)
 if kind=='v':return (2*a-r,c)
 if kind=='h':return (r,2*b-c)
