def d4_points(points,kind):
    res=[]
    for r,c in points:
        if kind=='id': q=(r,c)
        elif kind=='r90': q=(c,-r)
        elif kind=='r180':q=(-r,-c)
        elif kind=='r270':q=(-c,r)
        elif kind=='fv': q=(r,-c)
        elif kind=='fh':q=(-r,c)
        elif kind=='diag':q=(c,r)
        elif kind=='anti':q=(-c,-r)
        res.append(q)
    return set(res)
def fit_src_to_dst(source,destination):
  matches=[]
  for k in ['id','r90','r180','r270','fv','fh','diag','anti']:
    s=d4_points(source,k)
    for dr in range(-30,31):
      for dc in range(-30,31):
        t={(r+dr,c+dc) for r,c in s}
        if t==destination: matches.append((k,dr,dc))
  return matches
